import json
import os

from silence.settings import settings
from silence.exceptions import TestDefinitionError

###############################################################################
# Tests: definitions in tests/*.json.
#
# As with the endpoints, each table has up to two files:
#   tests/auto_<table>.json  generated by Silence from the endpoints (admin
#                            panel). Regenerating it overwrites it.
#   tests/<table>.json       custom tests, e.g., composed ones. Silence never
#                            touches them, except when the panel saves one.
# A test name cannot be in two files.
#
# A test is a list of steps; each one sends a request and checks the response:
#
#   "photos_flow": {
#       "description": "Create a photo, read it and delete it",
#       "steps": [
#           {"request": {"method": "POST", "path": "/photos", "as": 1,
#                        "body": {"title": "Test", "url": "x.jpg", "visibility": "Pública"}},
#            "expect": {"status": 201},
#            "save": {"id": "lastId"}},
#           {"request": {"method": "GET", "path": "/photos/${id}"},
#            "expect": {"status": 200, "row": {"title": "Test"}}},
#           {"request": {"method": "DELETE", "path": "/photos/${id}", "as": 1},
#            "expect": {"status": 200}}
#       ]
#   }
#
# request.as: the primary key of the user that sends the request (no
# password needed); null or missing: no session.
# expect: status, count (number of rows), row (fields of the first row or
# of the object), message (text contained in the error message).
# save: variables taken from the response ("lastId", "0.photo_id"...), to
# use as ${name} in the next steps.
###############################################################################

TESTS_DIR = "tests"
AUTO_PREFIX = "auto_"


def tests_dir():
    return os.path.join(settings.PROJECT_DIR, TESTS_DIR)


class Test:
    def __init__(self, name, data, filename):
        self.name = name
        self.file = os.path.basename(filename)
        stem = os.path.splitext(self.file)[0]
        self.table = stem[len(AUTO_PREFIX):] if stem.startswith(AUTO_PREFIX) else stem
        self.source = "auto" if self.file.startswith(AUTO_PREFIX) else "custom"
        self.data = data
        self.description = data.get("description", "")
        self.endpoint = data.get("endpoint", "")
        self.steps = data.get("steps")
        if not isinstance(self.steps, list) or not self.steps:
            raise TestDefinitionError(f"'{name}' in {self.file} has no steps")
        for i, step in enumerate(self.steps):
            req = step.get("request") if isinstance(step, dict) else None
            if not isinstance(req, dict) or "path" not in req:
                raise TestDefinitionError(f"'{name}' in {self.file}: step {i + 1} has no request.path")

    def to_dict(self):
        return {"name": self.name, "file": self.file, "table": self.table, "source": self.source,
                "description": self.description, "endpoint": self.endpoint,
                "composite": len(self.steps) > 1, "data": self.data}


class Suite:
    def __init__(self, tests, errors):
        self.tests = tests
        self.errors = errors

    def get(self, name):
        return next((t for t in self.tests if t.name == name), None)


def load_tests():
    tests, errors = [], []
    folder = tests_dir()
    files = sorted(f for f in os.listdir(folder) if f.endswith(".json")) if os.path.isdir(folder) else []
    for filename in files:
        path = os.path.join(folder, filename)
        if os.path.getsize(path) == 0:
            continue  # Just created by an editor: as if it did not exist yet
        try:
            with open(path, encoding="utf8") as f:
                content = json.load(f)
            if not isinstance(content, dict):
                raise TestDefinitionError(f"{filename} must contain an object with one entry per test")
        except (json.JSONDecodeError, TestDefinitionError) as exc:
            errors.append(f"{filename}: {exc}")
            continue
        for name, data in content.items():
            try:
                tests.append(Test(name, data, path))
            except (TestDefinitionError, AttributeError, TypeError) as exc:
                errors.append(str(exc))

    by_name = {}
    for t in tests:
        by_name.setdefault(t.name, []).append(t)
    duplicated = {n for n, ts in by_name.items() if len(ts) > 1}
    for n in sorted(duplicated):
        errors.append(f"the test '{n}' is in more than one file "
                      f"({', '.join(t.file for t in by_name[n])}): none of them is loaded")
    return Suite([t for t in tests if t.name not in duplicated], errors)
